"use client";
import { useRef, useState } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);
import { useGSAP } from '@gsap/react';
import { MessageCircle, Send } from 'lucide-react';

export default function Contato() {
  const sectionRef = useRef<HTMLElement>(null);
  const formRef = useRef<HTMLDivElement>(null);
  const infoRef = useRef<HTMLDivElement>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useGSAP(() => {
    if (!sectionRef.current) return;

    if (infoRef.current) {
      gsap.from(infoRef.current, {
        scrollTrigger: { trigger: sectionRef.current, start: 'top 80%' },
        x: -20, opacity: 0, duration: 0.8, ease: 'power3.out',
      });
    }

    if (formRef.current) {
      gsap.from(formRef.current, {
        scrollTrigger: { trigger: sectionRef.current, start: 'top 80%' },
        x: 20, opacity: 0, duration: 0.8, ease: 'power3.out',
      });
    }
  }, { scope: sectionRef });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      alert('Mensagem enviada com sucesso!');
      (e.target as HTMLFormElement).reset();
    }, 1200);
  };

  return (
    <section id="contato" ref={sectionRef} className="py-20 bg-bg-main relative">
      <div className="container mx-auto px-6 md:px-12">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-16 items-center">
          
          {/* Left: CTA */}
          <div ref={infoRef}>
            <span className="text-accent font-body text-xs font-bold tracking-widest uppercase mb-3 block">
              Agendamento
            </span>

            <h2 className="text-3xl md:text-4xl font-heading font-light text-primary-dark mb-4 leading-tight">
              Vamos cuidar da{' '}
              <span className="text-accent italic font-normal">sua pele</span> juntos?
            </h2>
            
            <p className="text-secondary-dark/70 font-body text-base leading-relaxed mb-8 max-w-md">
              Agende sua consulta para uma avaliação personalizada. Nosso compromisso é com a precisão clínica e o seu conforto.
            </p>

            <a 
              href="https://wa.me/5517999999999" 
              target="_blank" 
              rel="noopener noreferrer"
              className="inline-flex items-center gap-3 px-6 py-3 bg-primary-dark text-white rounded-full font-body text-sm tracking-wide hover:bg-accent transition-all duration-300 shadow-sm hover:shadow-md cursor-pointer"
            >
              <MessageCircle size={18} className="text-accent group-hover:text-white" />
              Agendar via WhatsApp
              <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse ml-1"></span>
            </a>
          </div>

          {/* Right: Form */}
          <div ref={formRef}>
            <div className="bg-white p-6 md:p-8 rounded-2xl shadow-sm border border-neutral-gray/10">
              <h3 className="text-lg font-heading font-medium text-primary-dark mb-1">
                Envie uma mensagem
              </h3>
              <p className="text-xs font-body text-secondary-dark/50 mb-5">
                Retornamos em até 24h úteis
              </p>
              
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label htmlFor="contact-name" className="font-body text-xs text-secondary-dark/70 mb-1 block">Nome</label>
                    <input type="text" id="contact-name" required placeholder="Seu nome"
                      className="w-full bg-bg-main border border-transparent rounded-lg px-3 py-2.5 font-body text-sm text-secondary-dark focus:border-accent focus:bg-white outline-none transition-all cursor-text" />
                  </div>
                  <div>
                    <label htmlFor="contact-phone" className="font-body text-xs text-secondary-dark/70 mb-1 block">WhatsApp</label>
                    <input type="tel" id="contact-phone" required placeholder="(17) 90000-0000"
                      className="w-full bg-bg-main border border-transparent rounded-lg px-3 py-2.5 font-body text-sm text-secondary-dark focus:border-accent focus:bg-white outline-none transition-all cursor-text" />
                  </div>
                </div>
                
                <div>
                  <label htmlFor="contact-email" className="font-body text-xs text-secondary-dark/70 mb-1 block">E-mail</label>
                  <input type="email" id="contact-email" required placeholder="seuemail@exemplo.com"
                    className="w-full bg-bg-main border border-transparent rounded-lg px-3 py-2.5 font-body text-sm text-secondary-dark focus:border-accent focus:bg-white outline-none transition-all cursor-text" />
                </div>

                <div>
                  <label htmlFor="contact-message" className="font-body text-xs text-secondary-dark/70 mb-1 block">Mensagem</label>
                  <textarea id="contact-message" rows={3} placeholder="Conte-nos o motivo do contato..."
                    className="w-full bg-bg-main border border-transparent rounded-lg px-3 py-2.5 font-body text-sm text-secondary-dark focus:border-accent focus:bg-white outline-none transition-all resize-none cursor-text"></textarea>
                </div>

                <button type="submit" disabled={isSubmitting}
                  className="w-full py-3 bg-primary-dark text-white rounded-full font-body text-sm tracking-wide transition-all duration-200 hover:bg-accent disabled:opacity-60 cursor-pointer flex items-center justify-center gap-2">
                  <Send size={14} />
                  {isSubmitting ? 'Enviando...' : 'Enviar Mensagem'}
                </button>
                
                <p className="font-body text-[10px] text-neutral-gray/60 text-center">
                  Dados protegidos pela LGPD.
                </p>
              </form>
            </div>
          </div>

        </div>
      </div>
    </section>
  );
}
